import{_ as s,h as n,i as e,c as i,v as t,p as l,x as r,m,e as p,S as h}from"./chunks/framework.Dvtg8yj2.js";const E=JSON.parse('{"title":"Mamba-2","description":"","frontmatter":{"title":"Mamba-2","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mamba-2.md","filePath":"llm/mamba-2.md","lastUpdated":1788454257000}'),S={name:"llm/mamba-2.md"};function d(b,a,M,c,_,f){const o=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="mamba-2" tabindex="-1">Mamba-2 <a class="header-anchor" href="#mamba-2" aria-label="Permalink to &quot;Mamba-2&quot;">​</a></h1><div class="epigraph"><p>同一条计算，既可以写成线性扫描，也可以写成一块结构化的注意力矩阵。</p><footer>Dao &amp; Gu，Mamba-2 / SSD，2024</footer></div><p>Mamba 已经能训练，也能在 SRAM 里扫描。真正卡住生态的是：这条扫描核和注意力侧已经打磨过的矩阵乘不在同一条路上。Mamba-2 不另起一套选择哲学，而是把选择性 SSM 收成能写成半可分矩阵的子类，于是同一层既可以扫描，也可以吃分块 GEMM。对偶是算法身份，不是口号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Mamba 已经证明选择性 SSM 能做语言模型，也证明扫描可以在 SRAM 里跑过墙钟。下一步的瓶颈不在「会不会选择」，而在<strong>计算原语和注意力的关系</strong>。扫描是递推；GPU 上最快的原语是矩阵乘。FlashAttention 把二次注意力切成能吃 Tensor Core 的块；Mamba 的扫描再快，也仍是递归核，和生态里已经极致优化的 GEMM 不在同一条路上。</p><p>同时，选择性 SSM 的数学身份不清楚。它看起来像 RNN，又像一种对注意力矩阵施加结构之后的退化。如果对偶写不出来，就很难借用注意力侧的掩码、变长、混合精度和编译栈，也很难判断该把状态扩到多宽。</p><p>Mamba-2 要回答的问题因此是：选择性 SSM 能否改写成对 GPU 友好的矩阵形式，并且这种形式与某种<strong>结构化注意力</strong>是同一件事。答案是 SSD——Structured State Space Duality。</p><h3 id="扫描核吃不满矩阵单元" tabindex="-1">扫描核吃不满矩阵单元 <a class="header-anchor" href="#扫描核吃不满矩阵单元" aria-label="Permalink to &quot;扫描核吃不满矩阵单元&quot;">​</a></h3><p>第一代 Mamba 的硬件感知实现已经避免把状态刷进 HBM，但核心循环仍是沿长度的 scan。序列短时，scan 的启动开销和低算术强度让它慢于同等 FLOP 的注意力；序列极长时它才稳定胜出。模型层若永远绑在 scan 上，就无法在中等长度上蹭到 Transformer 基础设施的红利。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SSD 把一类结构化 SSM 同时表示成两种算法：</p><ol><li><strong>递推形式</strong>：\\(h_t = a_t h_{t-1} + b_t x_t\\)，\\(y_t = c_t^\\top h_t\\)，线性时间、常数状态。</li><li><strong>矩阵形式</strong>：\\(y = M x\\)，其中 \\(M\\) 是由 \\((a,b,c)\\) 生成的半可分（semiseparable）矩阵，等价于对注意力矩阵施加「下三角 + 低秩结构」之后的乘法。</li></ol><p>两种形式在精确算术下给出同一条 \\(y\\)。于是「SSM 层」和「结构化注意力层」不再是两种模型，而是同一算子的两种因式分解。训练时可以选矩阵路径，吃分块 GEMM；推理时可以选递推路径，保持常数状态。这就是对偶。</p><h3 id="限制选择以换结构" tabindex="-1">限制选择以换结构 <a class="header-anchor" href="#限制选择以换结构" aria-label="Permalink to &quot;限制选择以换结构&quot;">​</a></h3><p>要对偶成立，不能让 \\(A_t\\) 是任意 dense 矩阵。Mamba-2 把每个通道的状态转移收成标量或对角，并把头的设计靠拢多头注意力：若干通道共享同一组 \\(a\\)，状态被扩得更宽，但每步的转移更简单。选择仍在输入相关的门上，只是门的形状被收成 SSD 需要的生成元。</p><p>换到公式里，矩阵 \\(M\\) 的条目大致满足</p> \\[M_{ij} = c_i^\\top \\Bigl(\\prod_{k=j+1}^{i} a_k\\Bigr) b_j \\quad (i \\ge j), \\]<p>上三角为零。这正是因果注意力矩阵的一种参数化：权重不是 \\(q_i^\\top k_j\\) 再 softmax，而是由扫描系数的前缀积生成。没有 softmax，也就没有二次归一化，数值路径更像线性注意力，但生成元来自 SSM 而不是核技巧。</p><h3 id="状态扩宽-核变简单" tabindex="-1">状态扩宽，核变简单 <a class="header-anchor" href="#状态扩宽-核变简单" aria-label="Permalink to &quot;状态扩宽，核变简单&quot;">​</a></h3><p>Mamba-1 用较小的状态宽 \\(N\\) 配复杂的输入相关 \\(\\bar A_t\\)。Mamba-2 把 \\(N\\) 拉大（常到 64、128 量级），把每步转移做成更接近对角、更适合张成矩阵块的形式。质量上，更宽的状态补偿了转移的简化；系统上，宽状态 × 简化转移，正好填满矩阵核的 tile。<span class="marginnote">更宽的 \\(N\\) 是为了填满 GEMM tile，也是为了补偿对角转移丢掉的通道混合。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="对偶给出两条实现路径" tabindex="-1">对偶给出两条实现路径 <a class="header-anchor" href="#对偶给出两条实现路径" aria-label="Permalink to &quot;对偶给出两条实现路径&quot;">​</a></h3><p>训练长序列、要高吞吐时，把 SSD 层当成「带结构的注意力」：构造或隐式乘以 \\(M\\)，用块状矩阵乘累积，不物化 \\(L \\times L\\) 全矩阵，只物化半可分生成元。解码、流式、常状态推理时，切回 scan，每步 \\(O(N)\\)。同一组权重，两种 schedule。</p>',23)),(e(),l(h,null,{default:r(()=>[p(o,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20Gen%5B%22%E7%94%9F%E6%88%90%E5%85%83%20a%2C%20b%2C%20c%22%5D%20--%3E%20Dual%7B%22SSD%20%E5%AF%B9%E5%81%B6%22%7D%0A%20%20Dual%20--%3E%20Scan%5B%22%E7%BA%BF%E6%80%A7%E6%89%AB%E6%8F%8F%20%2F%20%E5%B8%B8%E6%95%B0%E7%8A%B6%E6%80%81%22%5D%0A%20%20Dual%20--%3E%20Mat%5B%22%E5%8D%8A%E5%8F%AF%E5%88%86%E7%9F%A9%E9%98%B5%E4%B9%98%20%2F%20%E5%90%83%20GEMM%22%5D%0A%20%20Scan%20--%3E%20Y1%5B%22y%22%5D%0A%20%20Mat%20--%3E%20Y2%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%20y%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="与线性注意力、softmax-注意力的位置" tabindex="-1">与线性注意力、softmax 注意力的位置 <a class="header-anchor" href="#与线性注意力、softmax-注意力的位置" aria-label="Permalink to &quot;与线性注意力、softmax 注意力的位置&quot;">​</a></h3><p>SSD 矩阵没有 softmax，所以不是「稀疏化的 Transformer」。它更接近线性注意力：把 \\(L \\times L\\) 的核写成能递推的因子。差别在因子的来源。线性注意力用 \\(\\phi(q),\\phi(k)\\) 的外积累积；SSD 用 SSM 的前缀积 \\(a_{i:j}\\)。前缀积对衰减和选择有直接的时间尺度解释，这是 Mamba 一脉留下来的；矩阵视角则让它能接注意力代码里的分头、分块、掩码形状。<span class="marginnote">半可分生成元的秩受状态宽约束。对偶不是「任意注意力都可以写成扫描」。</span></p><p>Dao &amp; Gu（2024）把这件事说成「Transformers are SSMs」：不是所有 Transformer 都是 SSM，而是<strong>结构化</strong>的注意力（半可分、低秩生成元）与 SSM 重合。普通 softmax 注意力落在这个结构之外，所以对偶不是万能翻译，是给 Mamba 家族划出一块能吃矩阵核的子类。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>对偶的代价是表达力切口。能写成半可分生成元的注意力不是任意 \\(QK^\\top\\)。需要高度不规则、内容相关的检索模式时，SSD 仍可能不如全量 softmax。Mamba-2 用更宽状态和更深堆叠去补，工程上还常常在少数层插入真注意力——那已是 Jamba、Griffin 的课题，不是 SSD 本身。<span class="marginnote">训练走矩阵路径、解码走扫描，是同一组权重的两种 schedule，不是两套模型。</span></p><p>实现上，矩阵路径只有在 \\(L\\) 和 tile 匹配时才快；过短的序列、过窄的头，GEMM 同样吃不饱。扫描路径在超长解码上仍是正确的默认。把训练绑死在一种核上，会在另一端的长度上吃亏。数值上，前缀积 \\(\\prod a_k\\) 需要 log 域或仔细的缩放，否则长序列衰减到零或爆。这和 softmax 注意力的温度、缩放是同一类稳定性问题，只是出现在扫描系数而不是点积上。</p><p>Mamba-2 也没有取消选择性。没有输入相关的门，SSD 退回时不变 S4，对偶仍在，语言模型质量不在。论文的贡献是<strong>算法与结构</strong>，不是新的选择哲学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>Mamba-2（Dao &amp; Gu，2024）用 SSD 证明：一类选择性 SSM 与结构化（半可分）注意力是同一算子的两种写法。于是训练可以走矩阵核，推理可以走常数状态扫描。它让 Mamba 家族更好地吃 GPU，也划清了边界——对偶覆盖的是有生成元结构的注意力，不是任意 softmax。理解后续混合架构时，应把 Mamba-2 看成计算图上的一步，而不是又一个「RNN 击败 Transformer」的口号。</p>',9))])}const D=s(S,[["render",d]]);export{E as __pageData,D as default};
